INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(10201, '1 Chronicles 17:8', '1 Chronicles', 17, 8, '&nbsp;تۀ چې چرته هم تلے يې نو زۀ ستا مل وم او چې تۀ مخ په وړاندې تلې نو ما ستا ټولو دشمنانو له شکست ورکړے دے. زۀ به تا د دُنيا د لويو مشرانو په شان مشهور کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10202, '1 Chronicles 17:11', '1 Chronicles', 17, 11, '&nbsp;کله چې تۀ مړ شې او د خپل پلار نيکۀ سره ښخ شې، نو زۀ به ستا د زامنو نه يو زوئ بادشاه جوړ کړم او د هغۀ بادشاهى به مضبوطه کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10203, '1 Chronicles 17:12', '1 Chronicles', 17, 12, '&nbsp;هغه به هغه څوک وى چې زما دپاره يو کور جوړ کړى او زۀ به دا خبره يقينى کړم چې د هغۀ بادشاهى به د همېشه دپاره قائمه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10204, '1 Chronicles 17:13', '1 Chronicles', 17, 13, '&nbsp;زۀ به د هغۀ پلار يم او هغه به زما زوئ وى. زۀ به د هغۀ نه خپله نۀ ختمېدونکې مينه نۀ لرې کوم لکه څنګه چې ما د ساؤل نه لرې کړه، چې هغه ما د دې دپاره لرې کړو چې تۀ بادشاه شې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10205, '1 Chronicles 17:14', '1 Chronicles', 17, 14, '&nbsp;زۀ به هغه زما د کور او زما د بادشاهۍ د همېشه دپاره مشر جوړ کړم. د هغۀ بادشاهى به هيڅکله نۀ ختميږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10206, '1 Chronicles 17:15', '1 Chronicles', 17, 15, '&nbsp;ناتن داؤد ته هغه هر څۀ وفرمائيل چې مالِک خُدائ ورته په رويا کښې ښودلى وُو او کلام يې هم ورسره کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10207, '1 Chronicles 17:16', '1 Chronicles', 17, 16, '&nbsp;بيا داؤد بادشاه د مالِک خُدائ د حضور خېمې ته وردننه شو، کښېناستو او دُعا يې وکړه، ”مالِکه خُدايه، خُدايه پاکه، زۀ څوک يم او زما خاندان به څۀ وى چې تا مونږ تر دې پورې راورسولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10208, '1 Chronicles 17:17', '1 Chronicles', 17, 17, '&nbsp;خو تۀ نور هم ډېر څۀ کوې، تا په راتلونکى وخت کښې زما د اولاد په حقله وعدې کړې دى او مالِکه خُدايه، خُدايه پاکه، تۀ ما سره د يو اوچت مقام لرونکى کس په شان سلوک کوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10209, '1 Chronicles 17:18', '1 Chronicles', 17, 18, '&nbsp;زۀ نور تا ته څۀ ووايم. تۀ ما ښۀ پېژنې او بيا هم د خپل خِدمت کوونکى يعنې زما درناوے کوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10210, '1 Chronicles 17:19', '1 Chronicles', 17, 19, '&nbsp;اے مالِکه خُدايه، د خپل خِدمت کوونکى د خاطره، او د خپلې مرضۍ په مطابق تا دا ټول لوئ لوئ کارونه کړى او ښودلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10211, '1 Chronicles 17:20', '1 Chronicles', 17, 20, '&nbsp;مالِکه خُدايه، ستا په شان هيڅ څوک هم نشته، مونږ هيڅکله دا نۀ دى اورېدلى چې ستا په شان بل خُدائ پاک شته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10212, '1 Chronicles 17:21', '1 Chronicles', 17, 21, '&nbsp;د زمکې په مخ د بنى اِسرائيلو په شان بل قوم نشته، کوم چې تا په بيعه د غلامۍ نه آزاد کړل چې ستا خپل خلق شى. تا چې کوم لوئ او عجيبه کارونه کړى دى د هغې په وجه ستا نوم مشهور شو. تا خپل خلق د مِصر نه آزاد کړل او چې کله هغوئ مخ په وړاندې تلل نو تا هغه نور قومونه وشړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10213, '1 Chronicles 17:22', '1 Chronicles', 17, 22, '&nbsp;تا بنى اِسرائيليان د همېشه دپاره خپل خلق جوړ کړى دى او مالِکه خُدايه اوس تۀ د هغوئ خُدائ پاک جوړ شوے يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10214, '1 Chronicles 17:23', '1 Chronicles', 17, 23, '&nbsp;نو اوس، اے مالِکه خُدايه، تا چې زما او زما د اولاد په حقله کومې وعدې کړې دى هغه د همېشه دپاره پوره کړه او هغه څۀ وکړه چې تا د څۀ په حقله فرمائيلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10215, '1 Chronicles 17:24', '1 Chronicles', 17, 24, '&nbsp;ستا شُهرت به لوئ وى او خلق به د تل دپاره وائى چې، ”ربُ الافواج د بنى اِسرائيلو خُدائ پاک دے.“ او تۀ به د همېشه دپاره زما د اولاد د بادشاهۍ حِفاظت کوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10216, '1 Chronicles 17:25', '1 Chronicles', 17, 25, '&nbsp;زما خُدايه پاکه، زۀ دا جرأت کوم چې زۀ ستا نه دا سوال وکړم، ځکه چې دا هر څۀ تا خپل خِدمت کوونکى يعنې ما ته څرګند کړى دى او تا ما ته فرمائيلى دى چې تۀ به زما اولاد نه بادشاهان جوړوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10217, '1 Chronicles 17:26', '1 Chronicles', 17, 26, '&nbsp;مالِکه خُدايه، تۀ خُدائ پاک يې او تا د خپل خِدمت کوونکى سره د دې ښو څيزونو وعده کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10218, '1 Chronicles 17:27', '1 Chronicles', 17, 27, '&nbsp;نو زۀ تا ته سوال کوم چې زما اولاد له برکت ورکړه. مالِکه خُدايه، هغوئ به د همېشه دپاره ستا په برکت کښې پاتې شى او ستا برکت دې د همېشه دپاره د هغوئ سره وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10219, '1 Chronicles 18:1', '1 Chronicles', 18, 1, '&nbsp;څۀ موده وروستو داؤد بادشاه يو ځل بيا په فلستيانو حمله وکړه او شکست يې ورکړو. هغۀ د هغوئ د قبضې نه د جات ښار او ګېرچاپېره کلى واخستل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10220, '1 Chronicles 18:2', '1 Chronicles', 18, 2, '&nbsp;هغۀ موآبيانو له هم شکست ورکړو، او هغوئ د هغۀ د بادشاهۍ لاندې راغلل او هغۀ له يې محصُول ورکولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10221, '1 Chronicles 18:3', '1 Chronicles', 18, 3, '&nbsp;بيا، داؤد د ضوباه بادشاه هدد‌عزر له شکست ورکړو او د حمات پورې لاړو، ځکه چې کله هددعزر مخ په وړاندې تلو نو د فرات سيند پورې علاقه يې قبضه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10222, '1 Chronicles 18:4', '1 Chronicles', 18, 4, '&nbsp;داؤد د هغۀ يو زر جنګى ګاډۍ، اووۀ زره په آسونو سوارۀ سړى او شل زره پياده فوجيان ونيول. هغۀ دومره آسونه پرېښودل چې د سلو جنګى ګاډو دپاره کافى وُو او باقى چې کوم پاتې وُو نو هغه ټول يې ګوډ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10223, '1 Chronicles 18:5', '1 Chronicles', 18, 5, '&nbsp;کله چې د دمشق شاميانو د هدد‌عزر بادشاه د مدد دپاره يو لښکر ولېږلو، نو داؤد ورباندې حمله وکړه او دوويشت زره سړى يې ترې نه ووژل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10224, '1 Chronicles 18:6', '1 Chronicles', 18, 6, '&nbsp;بيا هغۀ د هغوئ په علاقه کښې فوجى کېمپونه ولګول او هغوئ د هغۀ د بادشاهۍ لاندې راغلل او هغۀ له يې محصُول ورکولو. مالِک خُدائ داؤد له په هر ځائ کښې فتح ورکوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10225, '1 Chronicles 18:7', '1 Chronicles', 18, 7, '&nbsp;داؤد د سرو زرو هغه ډالونه قبضه کړل چې کوم د هدد‌عزر آفسرانو وړل او دا يې يروشلم ته يوړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10226, '1 Chronicles 18:8', '1 Chronicles', 18, 8, '&nbsp;هغۀ د طِبخت او قون ښارونو نه په لوئ مِقدار کښې زېړ هم يوړل، چې په دې ښارونو باندې هدد‌عزر بادشاهى کوله. وروستو سليمان دا د زېړو ډيګۍ، ستنو او د عبادتخانې د زېړو د لوښو جوړولو دپاره استعمال کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10227, '1 Chronicles 18:9', '1 Chronicles', 18, 9, '&nbsp;د حمات بادشاه توعو خبر شو چې داؤد د هدد‌عزر ټول لښکر له شکست ورکړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10228, '1 Chronicles 18:10', '1 Chronicles', 18, 10, '&nbsp;نو هغۀ خپل زوئ هدورام ورولېږلو چې داؤد بادشاه ته ستړى مشى وکړى او په هدد‌عزر باندې د فتح موندلو مبارکى ورکړى، چې د هغۀ خِلاف توعو څو ځلې جنګېدلے وو. هدورام داؤد له تُحفې راوړې چې د سرو زرو، سپينو زرو او زېړو نه جوړې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10229, '1 Chronicles 18:11', '1 Chronicles', 18, 11, '&nbsp;داؤد بادشاه دا څيزونه وقف کړل چې په عبادت کښې استعمال شى، سره د هغه سپينو او سرو زرو چې د هغه قومونو نه يې اخستى وُو چې کوم يې فتح کړى وُو لکه چې ادوم، موآب، عمون، فلستيه او عماليق.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10230, '1 Chronicles 18:12', '1 Chronicles', 18, 12, '&nbsp;ابيشى چې د هغۀ مور ضروياه وه، هغۀ د مالګې په مېدان کښې ادوميانو له شکست ورکړو او د هغوئ نه يې اتلس زره کسان ووژل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10231, '1 Chronicles 18:13', '1 Chronicles', 18, 13, '&nbsp;هغۀ په ټول ادوم کښې فوجى کېمپونه ولګول او د هغه ځائ خلق د داؤد د بادشاهۍ لاندې راغلل. مالِک خُدائ داؤد له په هر ځائ کښې فتح ورکوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10232, '1 Chronicles 18:14', '1 Chronicles', 18, 14, '&nbsp;داؤد په ټولو بنى اِسرائيلو باندې حکومت کولو او دا خبره يې يقينى کړه چې د هغۀ د خلقو سره همېشه د حق او اِنصاف سلوک کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10233, '1 Chronicles 18:15', '1 Chronicles', 18, 15, '&nbsp;د ابيشى ورور يوآب د فوج مشر وو، د اخيلود زوئ يهوسفط منشى وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10234, '1 Chronicles 18:16', '1 Chronicles', 18, 16, '&nbsp;د اخيطوب زوئ صدوق او د ابياتار زوئ اخيمُلک اِمامان وُو، شَوشا د دربار منشى وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10235, '1 Chronicles 18:17', '1 Chronicles', 18, 17, '&nbsp;د يهويدع زوئ بناياه د داؤد د محافظانو مشر وو، او د داؤد زامنو د هغۀ په خِدمت کښې لوئې عُهدې لرلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10236, '1 Chronicles 19:1', '1 Chronicles', 19, 1, '&nbsp;څۀ موده وروستو عمونے بادشاه ناحس مړ شو او د هغۀ زوئ حنون بادشاه جوړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10237, '1 Chronicles 19:2', '1 Chronicles', 19, 2, '&nbsp;داؤد بادشاه وفرمائيل، ”زۀ به حنون ته خپله وفادارى هم هغه شان ښايم لکه څنګه چې د هغۀ پلار ناحس ما ته وفادارى ښودلې وه.“ نو داؤد پېغام وړُونکى ورولېږل چې هغۀ ته د خپلې غمرازۍ اظهار وکړى. کله چې هغوئ عمون ته ورسېدل او حنون بادشاه هغوئ راوغوښتل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10238, '1 Chronicles 19:3', '1 Chronicles', 19, 3, '&nbsp;نو د عمونيانو مشرانو بادشاه ته ووئيل، ”ستا خيال دا دے چې داؤد د غمرازۍ دپاره کوم سړى رالېږلى دى نو په دې وجه ستا د پلار عزت کيږى څۀ؟ په حقيقت کښې داسې نۀ ده. هغۀ دا د جاسوسۍ دپاره رالېږلى دى چې مُلک ولټوى، او فتح يې کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10239, '1 Chronicles 19:4', '1 Chronicles', 19, 4, '&nbsp;نو حنون د داؤد پېغام وړُونکى ونيول او د هغوئ نه يې ږيرې کلې کړې، د هغوئ چُوغې يې د کوناټو سره پرې کړې او هغوئ يې ولېږل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10240, '1 Chronicles 19:5', '1 Chronicles', 19, 5, '&nbsp;نو هغوئ دومره سخت شرمېدل چې خپلو کورونو ته نۀ شول واپس کېدلے. کله چې داؤد خبر شو چې څۀ شوى وُو، نو هغۀ هغوئ له خبر ورولېږلو چې په يريحو کښې ايسار شئ او تر هغې پورې واپس مۀ راځئ چې ترڅو پورې مو ږيرې بيا نۀ وى شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10241, '1 Chronicles 19:6', '1 Chronicles', 19, 6, '&nbsp;حنون بادشاه او عمونيانو ته پته ولګېده چې هغوئ داؤد بادشاه غصه کړے دے، نو هغوئ څلور دېرش زره کلو سپين زر ورکړل چې د برنى مسوپتاميه او د شامى علاقو معکه او ضوباه نه جنګى ګاډۍ او د ګاډو چلوونکى په مزدورۍ ونيسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10242, '1 Chronicles 19:7', '1 Chronicles', 19, 7, '&nbsp;هغۀ دوه دېرش زره جنګى ګاډۍ چې هغوئ په کرايه ونيولې او د معکه بادشاه لښکر راغلو او د ميدبا سره نزدې يې خېمې ولګولې. عمونيان هم د خپلو ټولو ښارونو نه راووتل او د جنګ دپاره تيار شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10243, '1 Chronicles 19:8', '1 Chronicles', 19, 8, '&nbsp;کله چې داؤد د حالاتو نه خبر شو، نو هغۀ يوآب او ټول لښکر ورولېږلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10244, '1 Chronicles 19:9', '1 Chronicles', 19, 9, '&nbsp;عمونيان روان شول او د شاهى ښار ربه دروازې سره يې د جنګ دپاره صفونه جوړ کړل او هغه بادشاهان چې کوم د مدد دپاره راغلى وُو نو هغوئ هم په کولاو مېدان کښې صفونه جوړ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10245, '1 Chronicles 19:10', '1 Chronicles', 19, 10, '&nbsp;يوآب ته پته ولګېده چې د دشمن لښکر به په هغۀ باندې د مخې او شا د طرف نه حمله وکړى، نو هغۀ ښۀ تکړه بنى اِسرائيلى فوجيان خوښ کړل او هغوئ يې د جنګ دپاره شاميانو ته مخامخ ودرول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10246, '1 Chronicles 19:11', '1 Chronicles', 19, 11, '&nbsp;هغۀ باقى پاتې فوجيان د خپل ورور ابيشى د مشرۍ لاندې راوستل، چې هغۀ دوئ د جنګ دپاره عمونيانو ته مخامخ ودرول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10247, '1 Chronicles 19:12', '1 Chronicles', 19, 12, '&nbsp;يوآب هغۀ ته ووئيل، ”کۀ تا ته پته ولګى چې شاميان ما له شکست راکوى، نو راشه او زما مدد وکړه او کۀ عمونيان تا له شکست درکوى، نو زۀ به درشم او ستا مدد به وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10248, '1 Chronicles 19:13', '1 Chronicles', 19, 13, '&nbsp;تکړه شه او حوصله مضبوطه کړه. راځئ چې د خپلو خلقو او زمونږ د خُدائ پاک د ښارونو دپاره سخت جنګ وکړُو. او د مالِک خُدائ مرضى دې پوره شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10249, '1 Chronicles 19:14', '1 Chronicles', 19, 14, '&nbsp;يوآب او د هغۀ سړى د حملې کولو دپاره وړاندې شول او شاميان وتښتېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10250, '1 Chronicles 19:15', '1 Chronicles', 19, 15, '&nbsp;کله چې عمونيانو وليدل چې شاميان منډې وهى، نو هغوئ د ابيشى نه وتښتېدل او ښار ته واپس ننوتل. بيا يوآب يروشلم ته واپس لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10251, '1 Chronicles 19:16', '1 Chronicles', 19, 16, '&nbsp;شاميانو ته پته ولګېده چې هغوئ د بنى اِسرائيلو نه شکست خوړلے دے، نو هغوئ د فرات سيند نمرخاتۀ طرف ته د شام علاقو نه فوجيان راوستل او هغوئ يې د سوفک د مشرۍ لاندې کړل، چې د ضوباه د هدد‌عزر بادشاه د لښکر مشر وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10252, '1 Chronicles 19:17', '1 Chronicles', 19, 17, '&nbsp;کله چې داؤد د دې نه خبر شو، نو هغۀ د بنى اِسرائيلو فوجيان راغونډ کړل، د اُردن سيند نه پورې وتل او شاميانو ته يې مخامخ د جنګ دپاره ودرول. او جنګ شروع شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10253, '1 Chronicles 19:18', '1 Chronicles', 19, 18, '&nbsp;او بنى اِسرائيلو د شاميانو فوج واپس وشړلو. داؤد او د هغۀ سړو اووۀ زره د شام د جنګى ګاډو چلوونکى او څلوېښت زره پېدل فوجيان ووژل. هغوئ د شاميانو د فوج مشر، سوفک هم ووژلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10254, '1 Chronicles 19:19', '1 Chronicles', 19, 19, '&nbsp;کله چې هغه بادشاهانو ته پته لګېده کوم چې د هدد‌عزر د بادشاهۍ لاندې وُو چې هغوئ د بنى اِسرائيلو نه شکست خوړلے دے، نو هغوئ د داؤد سره د امن تړون وکړو او د هغۀ د بادشاهۍ لاندې راغلل. شاميانو بيا هيڅکله دا ونۀ غوښتل چې د عمونيانو مدد وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10255, '1 Chronicles 20:1', '1 Chronicles', 20, 1, '&nbsp;په ورپسې سپرلى کښې، د کال په هغه وخت کښې چې بادشاهان عموماً د جنګ دپاره ځى، يوآب لښکر روان کړو او د عمون مُلک يې تباه کړو، اګر چې داؤد بادشاه په يروشلم کښې ايسار وو. هغوئ د ربه ښار محاصره کړو او په دې يې حمله وکړه او تباه يې کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10256, '1 Chronicles 20:2', '1 Chronicles', 20, 2, '&nbsp;د عمونيانو د بُت مولک يو د سرو زرو تاج وو چې تقريباً څلور دېرش کلو وزن يې وو. په دې کښې يو قيمتى کاڼے وو، کوم چې داؤد يوړو او په خپل تاج کښې يې ولګولو. هغۀ د هغه ښار نه ډېر زيات مالِ غنيمت هم يوړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10257, '1 Chronicles 20:3', '1 Chronicles', 20, 3, '&nbsp;هغۀ د ښار خلق بوتلل او په زور يې ترې نه د ارو، د اوسپنې کودالو او د تبرُونو کار اخستلو. هغۀ د عمون د نورو ټولو ښارونو په خلقو هم دغه شان وکړل. بيا هغه او د هغۀ سړى يروشلم ته را واپس شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10258, '1 Chronicles 20:4', '1 Chronicles', 20, 4, '&nbsp;وروستو په جزر کښې د فلستيانو سره جنګ بيا شروع شو. د جنګ په دوران کښې د حوسه سِبکى يو دېو ووژلو چې د هغه دېو نوم سفى وو. او فلستيانو شکست وخوړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10259, '1 Chronicles 20:5', '1 Chronicles', 20, 5, '&nbsp;د فلستيانو سره يو بل جنګ وشو او د يائير زوئ اِلحنان لحمى ووژلو، لحمى د جات د جوليت ورور وو، او د هغۀ د نېزې لاسکے د کوټې د تير هومره مضبوط وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10260, '1 Chronicles 20:6', '1 Chronicles', 20, 6, '&nbsp;په جات کښې يو بل جنګ وشو، چې په دې جنګ کښې يو دېو وو چې د هر لاس يې شپږ ګوتې او د هرې پښې يې هم شپږ ګوتې وې. هغه د پخوانو دېوانو اولاد وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10261, '1 Chronicles 20:7', '1 Chronicles', 20, 7, '&nbsp;کله چې هغۀ په بنى اِسرائيلو پورې ټوقې وکړې، نو يونتن هغه ووژلو، يونتن د داؤد د ورور د سِمعه زوئ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10262, '1 Chronicles 20:8', '1 Chronicles', 20, 8, '&nbsp;دا درې کوم چې داؤد او د هغۀ سړو وژلى وُو، هغوئ د جات د دېوانو اولاد وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10263, '1 Chronicles 21:1', '1 Chronicles', 21, 1, '&nbsp;شېطان غوښتل چې په بنى اِسرائيلو باندې مصيبت راولى، نو هغۀ داؤد ولمسولو چې يوه مردم‌شمارى وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10264, '1 Chronicles 21:2', '1 Chronicles', 21, 2, '&nbsp;نو داؤد يوآب او نورو آفسرانو له حُکم ورکړو، ”د بنى اِسرائيل مُلک د يو سر نه تر بل سر پورې وګرځئ او خلق وشمېرئ. ما له تفصيل راوړئ چې پته راته ولګى چې خلق څومره دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10265, '1 Chronicles 21:3', '1 Chronicles', 21, 3, '&nbsp;يوآب جواب ورکړو، ”بادشاه سلامت، مالِک خُدائ دې بنى اِسرائيليان د هغې نه يو په سل زيات کړى چې څومره اوس دى. هغوئ ټول ستا نوکران دى. تۀ ټول قوم ولې مجرم کول غواړې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10266, '1 Chronicles 21:4', '1 Chronicles', 21, 4, '&nbsp;خو بادشاه په يوآب باندې دا حُکم ومنلو. نو يوآب لاړو او هغه د بنى اِسرائيلو په ټول مُلک کښې وګرځېدو او يروشلم ته واپس راغلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10267, '1 Chronicles 21:5', '1 Chronicles', 21, 5, '&nbsp;هغۀ داؤد بادشاه د دې نه خبر کړو او د هغه ټولو سړو شمېر دا وو چا چې جنګ کولے شو: په بنى اِسرائيلو کښې يوولس لاکه او په يهوداه کښې څلور لاکه او اويا زره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10268, '1 Chronicles 21:6', '1 Chronicles', 21, 6, '&nbsp;يوآب د بادشاه حُکم ته سپک وکتل نو هغۀ ځکه د ليوى او بنيامين د قبيلو مردم‌شمارى ونۀ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10269, '1 Chronicles 21:7', '1 Chronicles', 21, 7, '&nbsp;چې څۀ شوى وُو خُدائ پاک په هغې ناراضه شو، نو هغۀ بنى اِسرائيلو له سزا ورکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10270, '1 Chronicles 21:8', '1 Chronicles', 21, 8, '&nbsp;داؤد خُدائ پاک ته وفرمائيل، ”ما د دې کار کولو سره يوه سخته ګناه کړې ده. زۀ تا ته سوال کوم چې زما غلطى معاف کړه. ما د ډېر کم عقلتوب نه کار اخستے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10271, '1 Chronicles 21:9', '1 Chronicles', 21, 9, '&nbsp;بيا مالِک خُدائ جاد ته وفرمائيل چا به چې د داؤد دپاره نبوت کولو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10272, '1 Chronicles 21:10', '1 Chronicles', 21, 10, '&nbsp;”لاړ شه او داؤد ته ووايه چې زۀ هغۀ له درې خوښې ورکوم. چې هغه کومه يوه خوښه کړى نو زۀ به هم هغه شان وکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10273, '1 Chronicles 21:11', '1 Chronicles', 21, 11, '&nbsp;نو جاد داؤد له لاړو او هغۀ ته يې وفرمائيل، ”مالِک خُدائ داسې فرمائى چې په دې کښې يوه خبره خوښه کړه:', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10274, '1 Chronicles 21:12', '1 Chronicles', 21, 12, '&nbsp;د قحط درې کالونه دې خوښ دى؟ يا چې خپل دشمن درباندې درې مياشتې تباهى راولى؟ او يا چې درې ورځې د مالِک خُدائ د تُورې لاندې راشې او هغه ستا په مُلک باندې يوه وبا راولېږى، او د خپلې فرښتې په ذريعه په ټولو بنى اِسرائيلو کښې مرګ راولى؟ نو تۀ فېصله وکړه چې زۀ مالِک خُدائ له څۀ جواب ورکړم، چا چې زۀ رالېږلے يم؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10275, '1 Chronicles 21:13', '1 Chronicles', 21, 13, '&nbsp;داؤد جاد ته وفرمائيل، ”زۀ د نااُميدۍ په حالت کښې يم. ما دې ته مۀ پرېږده چې د انسانانو لاسونو ته حواله شم. زۀ دې مالِک خُدائ ته حواله شم، ځکه چې د هغۀ رحم ډېر لوئ دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10276, '1 Chronicles 21:14', '1 Chronicles', 21, 14, '&nbsp;نو مالِک خُدائ په بنى اِسرائيلو باندې يوه وبا راولېږله او د هغوئ اويا زره کسان مړۀ شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10277, '1 Chronicles 21:15', '1 Chronicles', 21, 15, '&nbsp;بيا هغۀ د يروشلم د تباه کولو دپاره يوه تباه کوونکى فرښته راولېږله، خو د تباهۍ نه لږ مخکښې مالِک خُدائ خپله فېصله بدله کړه او د مرګ فرښتې ته يې وفرمائيل، ”بس کړه، دا تباهى کافى ده.“ هغه فرښته د يو يبوسى اُرنان د درمند سره ولاړه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10278, '1 Chronicles 21:16', '1 Chronicles', 21, 16, '&nbsp;داؤد فرښته وليده چې پاس په هوا کښې ولاړه وه او تُوره يې د يروشلم تباه کولو دپاره په خپل لاس کښې نيولې وه. بيا داؤد او د خلقو مشران، چا چې د ټاټ جامې اغوستې وې هغه ټول لاندې ټيټ شول او په زمکه يې سجده ولګوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10279, '1 Chronicles 21:17', '1 Chronicles', 21, 17, '&nbsp;داؤد دُعا وکړه، ”اے خُدايه پاکه، زۀ هغه څوک يم چا چې ګناه کړې ده. زۀ هغه څوک يم چا چې د مردم‌شمارۍ حُکم ورکړو. دې غريبانانو خلقو څۀ کړى دى؟ مالِکه خُدايه، زما خُدايه پاکه. ما او زما خاندان له سزا راکړه او خپل خلق بچ کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10280, '1 Chronicles 21:18', '1 Chronicles', 21, 18, '&nbsp;د مالِک خُدائ فرښتې جاد ته وفرمائيل چې داؤد ته ووايه چې هغه د مالِک خُدائ دپاره د اُرنان په درمند کښې يوه قربان‌ګاه جوړه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10281, '1 Chronicles 21:19', '1 Chronicles', 21, 19, '&nbsp;داؤد د مالِک خُدائ حُکم ومنلو او لاړو، هم هغه شان کار يې وکړو چې څنګه ورته جاد وئيلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10282, '1 Chronicles 21:20', '1 Chronicles', 21, 20, '&nbsp;هلته په درمند کښې اُرنان او د هغۀ څلورو زامنو غنم غوبل کول او کله چې هغوئ فرښته وليده، نو د هغۀ زامنو منډه کړه او پټ شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10283, '1 Chronicles 21:21', '1 Chronicles', 21, 21, '&nbsp;څنګه چې اُرنان داؤد بادشاه وليدو چې راورسېدو، نو هغه د درمند نه لاړو او د هغۀ په مخکښې د عزت نه ټيټ شو او په زمکه يې سجده ولګوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10284, '1 Chronicles 21:22', '1 Chronicles', 21, 22, '&nbsp;داؤد هغۀ ته وفرمائيل، ”په ما باندې خپل درمند خرڅ کړه، نو چې داسې زۀ د مالِک خُدائ دپاره يوه قربان‌ګاه جوړه کړم او چې د دې سره وبا بنده شى. نو زۀ به تا له د دې پوره قيمت درکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10285, '1 Chronicles 21:23', '1 Chronicles', 21, 23, '&nbsp;اُرنان ورته ووئيل، ”بادشاه سلامت، دا واخله او چې څۀ دې خوښه وى هغه وکړه. دا غوَيى دې د نذرانې په توګه په قربان‌ګاه باندې وسوزولې شى، د درمند دا تختې دې د خشاک په توګه استعمال شى او د نذرانې ورکولو دپاره دا غنم دى. دا هر څۀ زۀ تا له درکوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10286, '1 Chronicles 21:24', '1 Chronicles', 21, 24, '&nbsp;خو بادشاه جواب ورکړو، ”نه، زۀ به تا له پوره قيمت درکوم. زۀ به مالِک خُدائ ته داسې يوه نذرانه نۀ پېش کوم چې هغه ما ته مفت مِلاو شوې وى يا هغه ستا وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10287, '1 Chronicles 21:25', '1 Chronicles', 21, 25, '&nbsp;او هغۀ اُرنان له د درمند دپاره شپږ سوه د سرو زرو سيکې ورکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10288, '1 Chronicles 21:26', '1 Chronicles', 21, 26, '&nbsp;هغۀ هلته د مالِک خُدائ دپاره يوه قربان‌ګاه جوړه کړه او سوزېدونکې او د سلامتۍ نذرانې يې ورباندې پېش کړې. هغۀ دُعا وکړه او مالِک خُدائ د هغۀ دُعا قبوله کړه او په قربان‌ګاه باندې د نذرانو سوزولو دپاره مالِک خُدائ د آسمان نه اور راولېږلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10289, '1 Chronicles 21:27', '1 Chronicles', 21, 27, '&nbsp;مالِک خُدائ هغه فرښتې ته وفرمائيل چې خپله تُوره په کاش کښې واپس کېږده او فرښتې حُکم ومنلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10290, '1 Chronicles 21:28', '1 Chronicles', 21, 28, '&nbsp;نو د دې په وجه داؤد ته پته ولګېده چې مالِک خُدائ د هغۀ دُعا قبوله کړې ده، نو هغۀ د اُرنان په درمند کښې په قربان‌ګاه باندې قربانۍ پېش کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10291, '1 Chronicles 21:29', '1 Chronicles', 21, 29, '&nbsp;د مالِک خُدائ د حضور هغه خېمه کومه چې موسىٰ په بيابان کښې جوړه کړې وه او هغه قربان‌ګاه چې په کومه باندې قربانۍ سوزولے شوې په هغه وخت کښې لا په جبعون کښې د عبادت په ځائ کښې وې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10292, '1 Chronicles 21:30', '1 Chronicles', 21, 30, '&nbsp;خو داؤد د دې جوګه نۀ وو چې هلته لاړ شى او د خُدائ پاک عبادت وکړى، ځکه چې هغه د مالِک خُدائ د فرښتې د تُورې نه يرېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10293, '1 Chronicles 22:1', '1 Chronicles', 22, 1, '&nbsp;نو داؤد وفرمائيل، ”دا هغه ځائ دے چرته به چې د مالِک خُدائ، د خُدائ پاک کور وى. دلته به هغه قربان‌ګاه وى چرته چې بنى اِسرائيليان سوزېدونکې نذرانې پېش کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10294, '1 Chronicles 22:2', '1 Chronicles', 22, 2, '&nbsp;داؤد بادشاه هغه ټولو مسافرو له حُکم ورکړو کوم چې د بنى اِسرائيلو په مُلک کښې اوسېدل چې راغونډ شى او د هغوئ نه يې کار اخستلو. په هغوئ کښې څۀ کسانو د مالِک خُدائ د کور جوړولو دپاره کاڼى تيارول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10295, '1 Chronicles 22:3', '1 Chronicles', 22, 3, '&nbsp;هغۀ د مېخونو او د لرګى دروازو د تړلو د پټو دپاره په لوئ مِقدار کښې اوسپنه، او دومره ډېر زېړ ورکړل چې هيچا هم نۀ شُو تللے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10296, '1 Chronicles 22:4', '1 Chronicles', 22, 4, '&nbsp;هغۀ د صور او صيدا په خلقو باندې په يو لوئ شمېر کښې د دِيار لرګى راوړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10297, '1 Chronicles 22:5', '1 Chronicles', 22, 5, '&nbsp;داؤد وفرمائيل چې، ”زما زوئ سليمان چې د مالِک خُدائ کوم کور جوړوى نو هغه دې خامخا د شان شوکت والا او په دُنيا کښې مشهور وى. خو هغه کم عُمره او ناتجربه‌کاره دے، نو زۀ به د هغې دپاره تيارے وکړم.“ نو داؤد د خپل مرګ نه مخکښې ډېر زيات سامان تيار کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10298, '1 Chronicles 22:6', '1 Chronicles', 22, 6, '&nbsp;هغۀ خپل زوئ سليمان راوغوښتلو او حُکم يې ورکړو چې د مالِک خُدائ د بنى اِسرائيلو خُدائ پاک دپاره يو کور تيار کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10299, '1 Chronicles 22:7', '1 Chronicles', 22, 7, '&nbsp;داؤد هغۀ ته وفرمائيل، ”زما زويه، ما دا غوښتل چې د مالِک خُدائ زما د خُدائ پاک د درناوى دپاره يو کور جوړ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10300, '1 Chronicles 22:8', '1 Chronicles', 22, 8, '&nbsp;خو د مالِک خُدائ کلام په ما نازل شو چې، تا ډېر خلق وژلى دى او ډېر جنګونه دې کړى دى. نو چې ما کومه وينه تويه کړې ده د هغې په وجه به هغه ما دې ته پرې نۀ ږدى چې د هغۀ دپاره کور جوړ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');